import{_ as t,o,c as r,a5 as e}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"弹窗广告位 — Z-BlogPHP 弹窗广告插件","description":"","frontmatter":{"标题":"ZBlogPHP 弹窗广告插件 – 弹窗广告位","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["zblog主题插件"],"标签":["Cookie控制","Z-BlogPHP","公告弹窗","前端动画","响应式","广告投放","弹窗广告","网站弹窗","网页弹窗"]},"headers":[],"relativePath":"md/zblog主题插件/ZBlogPHP 弹窗广告插件 - 弹窗广告位.md","filePath":"md/zblog主题插件/ZBlogPHP 弹窗广告插件 - 弹窗广告位.md"}'),n={name:"md/zblog主题插件/ZBlogPHP 弹窗广告插件 - 弹窗广告位.md"};function l(d,a,h,i,s,b){return o(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="弹窗广告位-—-z-blogphp-弹窗广告插件" tabindex="-1">弹窗广告位 — Z-BlogPHP 弹窗广告插件 <a class="header-anchor" href="#弹窗广告位-—-z-blogphp-弹窗广告插件" aria-label="Permalink to &quot;弹窗广告位 — Z-BlogPHP 弹窗广告插件&quot;">​</a></h1><blockquote><p>为 Z-BlogPHP 网站提供 PC 端与移动端独立的弹窗广告位，支持 HTML 与文本双模式内容渲染，内置关闭 Cookie 定时隐藏机制与自定义 CSS 样式，帮助站长灵活投放广告与公告。</p></blockquote><p><strong>版本</strong>：v2.1.4<br><strong>适配</strong>：Z-BlogPHP 1.7.0+<br><strong>PHP</strong>：&gt;= 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-12.png" alt=""></p><p>本插件用于在 Z-BlogPHP 网站前台展示弹窗广告或公告内容，无需修改主题模板即可快速部署。插件在页面加载时自动注入弹窗 HTML 与样式脚本，通过 UA 检测自动区分 PC 端与移动端，分别加载对应的弹窗配置，确保在不同设备上都能获得合适的展示效果。</p><p>插件提供 HTML 模式与文本模式两种内容渲染方式：HTML 模式自动过滤 script 标签与事件属性，仅渲染安全的 HTML 内容；文本模式对所有输入进行 HTML 转义并采用公告风格展示，适合发布网站通知或声明。</p><p>用户点击关闭按钮后，插件通过 Cookie 记录关闭状态，在设定的时间范围内不再弹出，避免反复打扰访客。Cookie 有效期支持 1 秒至 86400 秒（24 小时）自由调节。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="pc-端与移动端独立弹窗" tabindex="-1">PC 端与移动端独立弹窗 <a class="header-anchor" href="#pc-端与移动端独立弹窗" aria-label="Permalink to &quot;PC 端与移动端独立弹窗&quot;">​</a></h3><p>插件为 PC 端和移动端各提供 3 个弹窗位置，共 6 个独立弹窗位，每个位置可分别配置内容与开关：</p><table tabindex="0"><thead><tr><th>端</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>PC 端</td><td>中间弹窗</td><td>页面中央弹出，适合重要公告或大型广告</td></tr><tr><td>PC 端</td><td>左下角弹窗</td><td>页面左下角固定，适合轻量提示或小尺寸广告</td></tr><tr><td>PC 端</td><td>右下角弹窗</td><td>页面右下角固定，适合客服引导或二维码推广</td></tr><tr><td>移动端</td><td>中间弹窗（移动）</td><td>移动端页面中央弹出，自适应屏幕宽度</td></tr><tr><td>移动端</td><td>左下角弹窗（移动）</td><td>移动端左下角固定，适合轻量提示</td></tr><tr><td>移动端</td><td>左下角弹窗（移动）</td><td>移动端左下角固定，适合轻量提示</td></tr></tbody></table><p>插件通过 User-Agent 自动识别访客设备类型，无需手动配置即可为不同设备加载对应的弹窗配置。</p><h3 id="html-与文本双模式" tabindex="-1">HTML 与文本双模式 <a class="header-anchor" href="#html-与文本双模式" aria-label="Permalink to &quot;HTML 与文本双模式&quot;">​</a></h3><p>每个弹窗位支持两种内容模式，可根据需求灵活选择：</p><p>— <strong>HTML 模式</strong>：直接渲染 HTML 内容，插件自动过滤 script 标签、onclick 等事件属性以及 javascript: 伪协议链接，确保安全性；<br> — <strong>文本模式</strong>：对所有输入内容进行 HTML 转义后渲染，采用公告风格界面展示，包含标题栏和正文区域，适合发布网站通知或声明。</p><h3 id="关闭-cookie-定时隐藏" tabindex="-1">关闭 Cookie 定时隐藏 <a class="header-anchor" href="#关闭-cookie-定时隐藏" aria-label="Permalink to &quot;关闭 Cookie 定时隐藏&quot;">​</a></h3><p>用户点击弹窗关闭按钮后，插件通过 Cookie 记录该弹窗的关闭状态：</p><p>— 在设定的秒数（1 至 86400 秒）内，同一浏览器不再重复弹出该弹窗；<br> — 每个弹窗位的 Cookie 独立管理，关闭 A 弹窗不影响 B 弹窗的展示；<br> — 支持同时展示多个已启用的弹窗，互不干扰。</p><h3 id="自定义-css-样式" tabindex="-1">自定义 CSS 样式 <a class="header-anchor" href="#自定义-css-样式" aria-label="Permalink to &quot;自定义 CSS 样式&quot;">​</a></h3><p>插件后台提供自定义 CSS 输入框，可直接编写样式覆盖弹窗默认外观。建议使用 <code>.tcad-</code> 前缀选择器限定作用域，避免影响网站其他元素。插件会在前台页面自动注入自定义样式，无需手动修改模板文件。</p><h3 id="每个弹窗独立配置" tabindex="-1">每个弹窗独立配置 <a class="header-anchor" href="#每个弹窗独立配置" aria-label="Permalink to &quot;每个弹窗独立配置&quot;">​</a></h3><p>每个弹窗位均支持以下独立设置：</p><p>— <strong>启用开关</strong>：一键开启或关闭该弹窗位；<br> — <strong>内容模式</strong>：HTML 模式或文本模式自由切换；<br> — <strong>标题</strong>：自定义弹窗标题文字（文本模式下显示在标题栏）；<br> — <strong>宽度与高度</strong>：支持 px、em、rem、%、vw、vh 等 CSS 单位，留空则使用默认尺寸；<br> — <strong>水印文字</strong>：弹窗角落显示广告标识文字（如”广告”），可独立控制显示或隐藏。</p><h3 id="中英文双语后台" tabindex="-1">中英文双语后台 <a class="header-anchor" href="#中英文双语后台" aria-label="Permalink to &quot;中英文双语后台&quot;">​</a></h3><p>插件后台管理界面支持中文和英文切换，所有字段标签、提示文字和按钮文本均随语言设置动态切换，方便不同语言习惯的站长使用。</p><h3 id="卸载配置可控" tabindex="-1">卸载配置可控 <a class="header-anchor" href="#卸载配置可控" aria-label="Permalink to &quot;卸载配置可控&quot;">​</a></h3><p>插件卸载时，用户可在后台设置中选择清空所有配置数据或保留配置。选择保留时，重新安装插件后将自动恢复之前的弹窗设置。</p><h3 id="响应式自适应" tabindex="-1">响应式自适应 <a class="header-anchor" href="#响应式自适应" aria-label="Permalink to &quot;响应式自适应&quot;">​</a></h3><p>弹窗样式针对移动端进行了响应式适配，在小屏幕设备上自动缩小弹窗尺寸，确保内容不被遮挡且关闭按钮始终可点击。文本模式弹窗在移动端自动降低正文字号和最大高度。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>tcad_tanchuang</code> 文件夹上传至网站 <code>zb_users/plugin/</code> 目录，进入 Z-BlogPHP 后台「插件管理」页面，找到「弹窗广告位」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-13.png" alt=""></p><h3 id="第二步-配置弹窗内容" tabindex="-1">第二步：配置弹窗内容 <a class="header-anchor" href="#第二步-配置弹窗内容" aria-label="Permalink to &quot;第二步：配置弹窗内容&quot;">​</a></h3><p>进入后台顶部菜单「弹窗广告位」或「插件管理 → 弹窗广告位 → 设置」：</p><p>— 在「全局设置」卡片中设置语言、关闭后隐藏秒数、水印文字、自定义 CSS 等全局参数；<br> — 在「PC 端弹窗广告」卡片中分别配置中间、左下角、右下角三个弹窗位的内容和开关；<br> — 在「移动端弹窗广告」卡片中分别配置移动端的三个弹窗位，如需在移动端展示相同的弹窗内容，可参考 PC 端配置同步填写；<br> — 每个弹窗位可独立选择 HTML 或文本模式，设置标题、宽高和水印显示状态；<br> — 如某个位置不需要弹窗，将启用开关关闭即可。</p><h3 id="第三步-提交保存" tabindex="-1">第三步：提交保存 <a class="header-anchor" href="#第三步-提交保存" aria-label="Permalink to &quot;第三步：提交保存&quot;">​</a></h3><p>点击页面底部的「提交」按钮保存所有配置。插件会将配置同时写入 Z-BlogPHP 数据库和 <code>config.json</code> 文件，确保数据不丢失。</p><h3 id="第四步-前台验证" tabindex="-1">第四步：前台验证 <a class="header-anchor" href="#第四步-前台验证" aria-label="Permalink to &quot;第四步：前台验证&quot;">​</a></h3><p>— 使用 PC 浏览器访问网站前台，检查配置的弹窗是否正常显示在对应位置；<br> — 使用移动设备或浏览器移动端模拟模式访问，确认移动端弹窗是否正确加载；<br> — 点击弹窗关闭按钮后刷新页面，验证弹窗是否在设定时间内不再出现；<br> — 如有自定义 CSS，检查样式是否按预期生效。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 插件在前台注入弹窗时会自动加载所需的 CSS 和 JS 文件，如网站使用了 CDN 或缓存插件，修改弹窗配置后建议清除缓存以确保最新内容生效；<br> — HTML 模式下插件会自动过滤 script 标签和事件属性，如需嵌入复杂交互内容，建议使用文本模式配合纯 HTML 样式实现；<br> — 关闭 Cookie 的有效期最大为 86400 秒（24 小时），如需更长的隐藏时间，请在 Cookie 有效期内不要清除浏览器 Cookie；<br> — 自定义 CSS 建议使用 <code>.tcad-</code> 前缀选择器编写，插件内置样式均使用该前缀以确保作用域隔离；<br> — 移动端弹窗的宽高设置应与 PC 端区分（如 PC 端中间弹窗设置 600px 宽度，移动端建议设置 90vw 或更小），避免在小屏幕上内容溢出。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v2-1-4-2026-06-27" tabindex="-1">v2.1.4（2026-06-27） <a class="header-anchor" href="#v2-1-4-2026-06-27" aria-label="Permalink to &quot;v2.1.4（2026-06-27）&quot;">​</a></h3><p>— 新增文本模式公告风格弹窗，支持标题栏和正文区域独立渲染；<br> — 新增中英文双语后台界面，所有文案支持语言切换；<br> — 新增自定义 CSS 输入与前台注入功能；<br> — 新增卸载时清空/保留配置选项；<br> — 新增移动端 User-Agent 自动识别，PC 与移动端弹窗独立配置；<br> — 优化 HTML 模式安全过滤机制，自动去除 script 标签、事件属性和 javascript: 协议链接；<br> — 优化 Cookie 管理逻辑，每个弹窗位独立记录关闭状态；<br> — 优化弹窗动画效果，底部位置从边缘滑入，中央位置从顶部滑入。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2990.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2990.html</a></p>',50)])])}const g=t(n,[["render",l]]);export{c as __pageData,g as default};
